/* Markup: <div class="fx-blueprint">DRAFT</div> */

/* Colour tokens — override to re-skin the effect:
   --ink    main text colour (defaults to currentColor)
   --ink-2  primary accent   --ink-3  secondary accent */
:root { --ink: currentColor; --ink-2: #FF4FD8; --ink-3: #4FF8FF; }

/* 35 Blueprint */
.fx-blueprint {
  font: 600 28px/1.15 JetBrains Mono, monospace;
  letter-spacing: .1em;
  color: transparent;
  padding: .28em .45em;
  -webkit-text-stroke: 1px color-mix(in srgb, var(--ink-3) 80%, var(--ink));
  background: linear-gradient(90deg, color-mix(in srgb, var(--ink-3) 22%, transparent) 1px, transparent 1px), linear-gradient(0deg, color-mix(in srgb, var(--ink-3) 18%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in srgb, var(--ink-3) 42%, transparent), transparent 35% 65%, color-mix(in srgb, var(--ink-3) 42%, transparent));
  background-size: 12px 12px, 12px 12px, 240% 100%;
  background-position: 0 0, 0 0, 100% 0;
  border: 1px solid color-mix(in srgb, var(--ink-3) 42%, transparent);
  box-shadow: inset 0 0 18px color-mix(in srgb, var(--ink-3) 18%, transparent);
  animation: fx-blueprint 4s linear infinite;
}
@keyframes fx-blueprint {
  to {
    background-position: 24px 0, 0 24px, -100% 0;
  }
}
